listeners.render:
function(x) {	
	var routeNo = this.previousSibling().getValue();
	var payload =routeNo.substring(0, routeNo.indexOf('/workItems'))+'/data/payload.json';
	var response = CQ.utils.HTTP.get(payload); 
	if (CQ.HTTP.isOk(response)){
		var myObject = CQ.Util.eval(response);
		if(myObject.path  && myObject.path != 'undefined'){
			var pagePath = myObject.path + '/jcr:content.json'
			var pageresponse = CQ.utils.HTTP.get(pagePath);
			if (CQ.HTTP.isOk(pageresponse)){ 
				var pageObject = CQ.Util.eval(pageresponse);
				if(pageObject && pageObject.productDivision){
					this.setValue(pageObject.productDivision);
				}
			}
		}
	}
}
